/* Editable synthetic assessments, stored separately from imported source records. */
state.assessments??={};state.customPatients??=[];state.assessmentHistory??=[];
let sourcePatients=null;const baseRender=render,baseAssess=assess,baseOverview=overview,basePatientDetail=detail;
const assessmentFields=[
['Identity & presentation',[
 ['Patient ID','Patient ID','id'],['Diagnosis','Diagnosis / synthetic label','text'],['Age (years)','Age (years)','number',18,120],['Cancer category','Cancer category','select',['Solid tumour','Haematological malignancy','Multiple myeloma']],['Days since last chemo','Days since chemotherapy','number',0,365],['Temp (°C)','Temperature (°C)','number',30,45],['Temperature method','Temperature method','select',['Oral','Other / unknown']],['Fever duration (hours)','Duration at ≥38°C (hours)','number',0,1000],['ANC (×10⁹/L)','ANC (×10⁹/L)','number',0,100],['Expected ANC below 0.5 in 48h','Expected ANC <0.5 within 48 hours','yesno'],['Systolic BP (mmHg)','Systolic BP (mmHg)','number',30,300],['Heart rate (bpm)','Heart rate (bpm)','number',20,250],['CrCl (mL/min)','Creatinine clearance (mL/min)','number',0,250]
]],['MASCC components',[
 ['Burden of illness','Burden of illness','select',['None/mild','Moderate','Severe']],['COPD','COPD','yesno'],['Previous fungal infection','Previous fungal infection','yesno'],['Dehydration needing IV fluids','Dehydration requiring IV fluids','yesno'],['Setting at fever onset','Setting at fever onset','select',['Outpatient','Inpatient']]
]],['Additional high-risk features',[
 ['Mucositis grade 3–4','Severe mucositis (grade 3–4)','yesno'],['Pneumonia / complex infection','Pneumonia / complex infection','yesno'],['Catheter infection','Catheter infection','yesno'],['Expected ANC <0.1 for ≥7 days','Expected ANC <0.1 for ≥7 days','yesno'],['AST/ALT >5× ULN','AST/ALT >5× ULN','yesno'],['New confusion / neuro change','New confusion / neurological change','yesno']
]]];
const additionalKeys=assessmentFields[2][1].map(f=>f[0]);
assess=function(p){let a=baseAssess(p);if(!p._editableAssessment)return a;const missing=additionalKeys.filter(k=>!['Yes','No'].includes(p[k]));if(p['CrCl (mL/min)']===null||p['CrCl (mL/min)']===undefined)missing.push('CrCl (mL/min)');const unknownMascc=['COPD','Previous fungal infection','Dehydration needing IV fluids'].some(k=>!['Yes','No'].includes(p[k]));if(unknownMascc)return{score:null,risk:a.flags.some(x=>!x.includes('Incomplete')&&!x.includes('Unrecognized'))?'High':'Unknown',flags:[...a.flags,'MASCC inputs incomplete']};if(missing.length&&a.risk==='Low')return{...a,risk:'Unknown',flags:[...a.flags,'Incomplete additional-risk screen: '+missing.join(', ')]};return a};
render=function(){if(patients.length&&!sourcePatients)sourcePatients=patients.map(p=>({...p}));if(sourcePatients){const selectedId=selected&&id(selected);patients=[...sourcePatients,...state.customPatients].map(p=>state.assessments[id(p)]?{...p,...state.assessments[id(p)]}:p);if(selectedId)selected=patients.find(p=>id(p)===selectedId)||null;}baseRender()};
overview=function(){let h=baseOverview();const high=patients.filter(p=>assess(p).risk==='High').length,low=patients.filter(p=>assess(p).risk==='Low').length,unknown=patients.filter(p=>assess(p).risk==='Unknown').length;h=h.replace(metricCard('heart','Low-risk pathway',patients.length-high,'Review low-risk patients','Low','mint'),metricCard('heart','Low-risk pathway',low,'Review low-risk patients','Low','mint'));h=h.replace('<button class="btn primary" onclick="go(\'Integration\')">Result inbox ↗</button>',`<div class="actions" style="margin:0"><button class="btn" onclick="go('Integration')">Result inbox ↗</button><button class="btn primary" onclick="openAssessment(true)">＋ New synthetic case</button></div>`);h=h.replace('<option '+(filter==='Low'?'selected':'')+'>Low</option>', '<option '+(filter==='Low'?'selected':'')+'>Low</option><option '+(filter==='Unknown'?'selected':'')+'>Unknown</option>');if(unknown)h=h.replace('<div class="panel"><div class="sectiontitle"><h2>Patient list',`<button class="btn" style="margin-bottom:16px" onclick="openMetric('Unknown')">${unknown} incomplete assessment${unknown===1?'':'s'} — review →</button><div class="panel"><div class="sectiontitle"><h2>Patient list`);return h};
detail=function(){let h=basePatientDetail();if(!selected)return h;const pid=id(selected),edited=!!state.assessments[pid],isNew=state.customPatients.some(p=>id(p)===pid);h=h.replace('<div class="patientbar">',`<div class="assessmentactions"><button class="btn primary" onclick="openAssessment(false)">Edit assessment</button><button class="btn" onclick="openAssessmentHistory()">Assessment history</button>${!isNew?`<button class="btn" onclick="showSourceRecord()">Original Excel record</button>`:''}</div><div class="patientbar">`);if(edited)h=h.replace('Workbook baseline','Saved demo assessment').replaceAll('Workbook · time not supplied','Saved assessment · '+fmt(state.assessments[pid]._savedAt));if(patientTab==='Summary'){let fn=fnEligibility(selected);h=h.replace('<div class="grid2">',`<div class="banner"><b>FN criteria: ${esc(fn.status)}</b><br>${esc(fn.reason)} · Draft educational rule; clinician review required.</div><div class="grid2">`)}return h};
function fnEligibility(p){const temp=p['Temp (°C)'],anc=p['ANC (×10⁹/L)'],duration=p['Fever duration (hours)'];const fever=typeof temp==='number'&&(temp>=38.3||(temp>=38&&typeof duration==='number'&&duration>=1));const neutro=typeof anc==='number'&&anc<.5||p['Expected ANC below 0.5 in 48h']==='Yes';if(fever&&neutro&&p['Temperature method']==='Oral')return{status:'Numeric criteria met',reason:'Oral fever criterion and current / anticipated ANC criterion documented'};if(temp==null||anc==null||p['Temperature method']!=='Oral'||temp>=38&&temp<38.3&&duration==null||anc>=.5&&p['Expected ANC below 0.5 in 48h']==null)return{status:'Incomplete assessment',reason:'Review temperature method, duration, ANC and anticipated decline; missing information does not exclude FN'};return{status:'Not established from entered criteria',reason:'Entered numeric criteria do not establish FN; clinical concern can still require urgent evaluation'};}
function assessmentInput(f,p,newCase){const [key,label,type,a,b]=f,v=p[key]??'',name=esc(key);if(type==='id')return `<label class="field">${label}<input name="${name}" value="${esc(v)}" ${newCase?'required pattern="[A-Za-z0-9_-]{3,40}"':'readonly'} maxlength="40"></label>`;if(type==='yesno'||type==='select'){const options=type==='yesno'?['Yes','No']:a;return `<label class="field">${label}<select name="${name}"><option value="">Unknown / not documented</option>${options.map(o=>`<option ${o===v?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`}return `<label class="field">${label}<input name="${name}" value="${esc(v)}" type="${type==='number'?'number':'text'}" ${type==='number'?`min="${a}" max="${b}" step="any"`: 'maxlength="120"'} ${key==='Age (years)'?'required':''}></label>`}
function openAssessment(newCase){const proposed='DEMO-'+String(state.customPatients.length+1).padStart(3,'0');let p=newCase?{'Patient ID':proposed}:selected;openDialog(newCase?'New synthetic patient':'Edit assessment · '+esc(id(p)),`<p>Use invented cases only. Unknown fields remain unknown. Saved edits are separate from the imported workbook.</p><form id="assessmentForm" onsubmit="event.preventDefault();saveAssessment(this,${newCase})">${assessmentFields.map(([heading,fields],i)=>`<details ${i===0?'open':''}><summary>${heading}</summary><div class="grid2" style="margin-top:18px">${fields.map(f=>assessmentInput(f,p,newCase)).join('')}</div></details>`).join('')}<p id="assessmentError" role="alert" style="color:#ad4538"></p><div class="actions"><button class="btn primary" type="submit">Save & recalculate</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#workflowDialog').classList.add('assessmentdialog')}
function parseAssessment(data){const p={_editableAssessment:true,_savedAt:new Date().toISOString()};for(const [,fields] of assessmentFields)for(const f of fields){const [key,,type,min,max]=f,raw=String(data.get(key)??'').trim();if(type==='number'){if(!raw){p[key]=null;continue}let n=Number(raw);if(!Number.isFinite(n)||n<min||n>max)throw Error('Check '+key);p[key]=n}else{if(type==='id'&&!/^[A-Za-z0-9_-]{3,40}$/.test(raw))throw Error('Use a 3–40 character synthetic ID (letters, digits, - or _).');if(type==='yesno'&&raw&&!['Yes','No'].includes(raw))throw Error('Invalid '+key);if(type==='select'&&raw&&!f[3].includes(raw))throw Error('Invalid '+key);p[key]=raw||null}}if(p['Age (years)']===null)throw Error('Adult age is required');return p}
function saveAssessment(form,isNew){try{const p=parseAssessment(new FormData(form)),pid=id(p);if(isNew&&patients.some(x=>id(x)===pid))throw Error('Patient ID already exists.');if(!isNew&&pid!==id(selected))throw Error('Patient identity cannot be changed here.');const a=assess(p);if(isNew)state.customPatients.push({'Patient ID':pid,Diagnosis:p.Diagnosis||'Synthetic case','MASCC score':null,'Final risk group':null});state.assessmentHistory.unshift({patientId:pid,time:p._savedAt,before:state.assessments[pid]||null,after:{...p},result:a});state.assessments[pid]=p;closeDialog();selected=p;patientTab='Summary';view='Patient assessment';save((isNew?'Created synthetic patient':'Updated synthetic assessment')+'; MASCC '+(a.score??'incomplete')+'; risk '+a.risk,pid)}catch(e){document.querySelector('#assessmentError').textContent=e.message}}
function openAssessmentHistory(){const history=state.assessmentHistory.filter(x=>x.patientId===id(selected));openDialog('Assessment history · '+esc(id(selected)),history.length?history.map(h=>`<div class="stage"><b>${esc(fmt(h.time))}</b><p>MASCC ${h.result.score??'incomplete'} · ${esc(h.result.risk)} risk</p><p>${esc(h.result.flags.join('; ')||'No additional recorded flags')}</p></div>`).join(''):'<p>No saved assessment changes for this case.</p>')}
function showSourceRecord(){const p=sourcePatients.find(p=>id(p)===id(selected));if(!p)return;openDialog('Original Excel record · '+esc(id(p)),`<p>Read-only imported source. Your local assessment edits do not modify this record.</p><div class="scroll"><table><tbody>${Object.entries(p).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>`)}
